contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run a single transaction that may send ETH to c and then attempts withdrawAll
    function run(address ownerAddr, address payable recipient, uint256 fundAmount, bool callAsOwner) public payable {
        require(address(this).balance >= fundAmount);
        // initial contract owner must match ownerAddr: deployer provided C has constructor(ownerAddr)
        // Fund c by sending Ether from this contract
        if (fundAmount > 0) {
            // transfer Ether to C
            (bool sent,) = address(c).call{value: fundAmount}("");
            require(sent);
        }

        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;

        bool reverted;
        if (callAsOwner) {
            // attempt withdrawal as owner: we must call through c using its withdrawAll where msg.sender is this contract
            // To simulate being the owner, the provided ownerAddr must equal address(this).
            // If ownerAddr != address(this) the call is expected to revert.
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // attempt withdrawal as non-owner (msg.sender != owner)
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // General rule:
        // - If this contract is the owner (i.e. c.owner() == address(this)) then the call must not revert and
        //   the entire balance of c is transferred to recipient (afterRecipient == beforeRecipient + beforeC) and c.balance becomes zero.
        // - Otherwise, the call must revert and balances remain unchanged.
        bool amOwner = (c.owner() == address(this));

        assert(
            (amOwner && !reverted && afterC == 0 && afterRecipient == beforeRecipient + beforeC)
            || (!amOwner && reverted && afterC == beforeC && afterRecipient == beforeRecipient)
        );
    }

    receive() external payable {}
}

