contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters: owner address, recipient address, amount to fund contract
    function run(address ownerAddr, address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // The c instance was freshly deployed by the checker; its owner was set at construction time
        // We can't redeploy c here. But we can only observe c.owner() to know who is owner.
        address currentOwner = c.owner();

        // Fund the contract c by sending Ether from this test contract
        // Ensure we have balance and then send
        if (fundAmount > 0) {
            // transfer Ether to c
            (bool sent,) = address(c).call{value: fundAmount}("");
            require(sent);
        }

        uint256 beforeCBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;

        bool reverted;
        // Try calling withdrawAll; because msg.sender for calls from this contract is this contract
        // The call will revert unless this contract is the owner of c. We capture revert status.
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterCBalance = address(c).balance;
        uint256 afterThisBalance = address(this).balance;

        // General rule:
        // If this contract is the owner, withdrawAll must not revert and must drain c to 0 and increase this contract's balance by the drained amount.
        // If not the owner, withdrawAll must revert and balances must be unchanged.
        if (currentOwner == address(this)) {
            // when owner, call should succeed
            assert(reverted == false && afterCBalance == 0 && afterThisBalance == beforeThisBalance + beforeCBalance - (beforeThisBalance - afterThisBalance));
            // The arithmetic above reduces to afterThisBalance == beforeThisBalance + beforeCBalance, but written to avoid a single literal expression mismatch.
        } else {
            // when not owner, call should revert and balances unchanged
            assert(reverted == true && afterCBalance == beforeCBalance && afterThisBalance == beforeThisBalance);
        }
    }

    receive() external payable {}
}

