contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address initialOwner, address recipient, uint amount, bool callAsOwner) public payable {
        require(address(this).balance >= amount);
        // We need to ensure the contract c was constructed with initialOwner = owner
        // The checker deploys a fresh c before calling run; but constructor already ran externally.
        // We can only observe c.owner() to get owner.

        // Fund the contract c by sending Ether from this contract
        // send amount to c
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        // read balance before
        uint before = address(c).balance;
        address ownerAddr = c.owner();

        bool reverted;
        if (callAsOwner) {
            // try calling as owner: we must make msg.sender == owner; but msg.sender will be this test contract.
            // To simulate owner calling, require that ownerAddr == address(this); otherwise this branch will attempt call and should revert.
            if (ownerAddr == address(this)) {
                try c.withdrawAll(recipient) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                // If owner is not this contract, then calling withdrawAll from this contract must revert due to require
                try c.withdrawAll(recipient) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        } else {
            // call as non-owner (this contract). If this contract happens to be the owner, then it's effectively owner call;
            // we still perform the call and record revert flag.
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint after = address(c).balance;
        uint receivedAtThis = address(this).balance;

        // General rule:
        // - If the call did not revert AND msg.sender (this) was equal to owner at time of call, then c.balance must be zero after and decreased by before;
        // - If the call reverted OR msg.sender was not owner at time of call, then c.balance must remain equal to before.
        // We express it without underflow: compare after == 0 when successful owner-call, else after == before.
        bool wasOwner = (ownerAddr == address(this));
        assert((!reverted && wasOwner && after == 0) || (reverted || !wasOwner) && (after == before));
    }

    // accept Ether
    receive() external payable {}
}

