contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes: caller (address to act as owner in constructor), recipient for withdrawal,
    // and an amount to fund the contract before attempting withdraw
    function run(address _owner, address payable _recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Deploy-time owner was set in the provided fresh c by the harness; however
        // the problem statement says c is a fresh deployed C passed into constructor of this test.
        // We cannot redeploy c, so we assume c was constructed with some owner. To make the test
        // meaningful we will compare behavior when this test contract (msg.sender) is owner vs not.

        // First, fund the contract c by sending Ether from this test contract
        // Note: send by calling its fallback payable
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent);

        // Record balances before withdraw
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = _recipient.balance;
        address ownerAddr = c.owner();

        // Attempt withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = _recipient.balance;

        // General rule asserted:
        // If the call did not revert then msg.sender (this contract) must have been the owner
        // AND all Ether previously held by c was transferred to recipient (c balance becomes zero and recipient increases by beforeC)
        // If the call reverted then either msg.sender was not owner or no funds moved (c balance unchanged and recipient unchanged).
        assert(
            // Success case: not reverted implies this contract is owner and funds moved out fully
            (!reverted && ownerAddr == address(this) && afterC == 0 && afterRecipient == beforeRecipient + beforeC)
            ||
            // Revert case: either not owner and no funds moved, or (if owner but still reverted) treat as revert: require funds unchanged
            (reverted && afterC == beforeC && afterRecipient == beforeRecipient)
        );
    }

    // allow receiving Ether
    receive() external payable {}
}

