    constructor(C _c) { c = _c; }

    // params: recipient to withdraw to, amount to fund c with before withdraw
    function run(address _recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Fund c by sending Ether to its fallback via low-level call to make C's balance increase
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent);

        // Observe before-values
        uint256 beforeC = address(c).balance;
        address recordedOwner = c.owner();

        // Attempt withdrawAll and record if it reverted
        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint256 afterC = address(c).balance;

        // General rule:
        // If the call succeeded then the recorded owner must be this contract and C's balance becomes zero.
        // If the call reverted then C's balance remains unchanged.
        assert((!reverted && recordedOwner == address(this) && afterC == 0) || (reverted && afterC == beforeC));
    }

    receive() external payable {}
}

