        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent, "funding failed");

        // read pre-state: owner and contract balance
        address ownerBefore = c.owner();
        uint256 balBefore = address(c).balance;

        // decide who will call withdrawAll: if caller equals ownerBefore, then this contract will act as owner by calling directly only when ownerBefore == address(this)
