        // If caller != address(this), we cannot actually change msg.sender, so we encode expectation: caller == ownerBefore must be equivalent to address(this) == ownerBefore for withdraw to succeed.
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint256 balAfter = address(c).balance;

